																				"css": "#logoCustomer {\n\ttext-align: left;\n\twidth: 20%;\n\tfloat: left;\n\tcolor: #1a2732;\n}\n\n#infoCustomer {\n\ttext-align: left;\n\twidth: 80%;\n\tmargin-bottom: 15px;\n\tdisplay: inline-block;\n}\n\n\t#infoCustomer .customerName {\n\t\tfont-size: 20px;\n\t\tline-height: 1.4;\n\t\tfont-weight: bold;\n\t\tcolor: #1a2732;\n\t\twhite-space: normal;\n\t}\n\n\t#infoCustomer .customerNumber {\n\t\tfont-size: 16px;\n\t\tline-height: 1.6;\n\t\tcolor: #1a2732;\n\t}\n\n\t#infoCustomer .customerStatus {\n\t\tfont-size: 14px;\n\t\tline-height: 1.6;\n\t\tcolor: #008998;\n\t}\n\n.nameContact {\n\tmargin-left: 10px;\n\tcolor: #1a2732;\n\tfont-size: 18px;\n\tmargin-bottom: 10px;\n\tpadding-top: 10px;\n\twhite-space: normal;\n}\n",
