																			"options": {
																				"label": "_AlertContainer",
																				"width": "100%",
																				"htmlContent": "<input id=\"onDisplayAlert\" type=\"hidden\" onclick=\"OnAddAlert(event);\">\n<input id=\"onAlertSetdetailsBtnVisibility\" type=\"hidden\" onclick=\"OnAlertSetdetailsBtnVisibility(event);\">\n<input id=\"onHideAlert\" type=\"hidden\" onclick=\"OnHideAlert(event);\">\n<div id=\"alertsContainer\"></div>\n\n<script>\n\twindow.postMessage({ eventName: \"onLoad\", control: \"AlertsContainer__\" }, document.location.origin);\n\n\tvar alerts = {};\n\tvar Alert = function (opt, containerElem)\n\t{\n\t\tfunction $getBtn(def, className, idName, callbackName, callBackFuncName)\n\t\t{\n\t\t\tvar btnElem = document.createElement(\"button\");\n\t\t\tbtnElem.innerText = def.title;\n\t\t\tbtnElem.className = className;\n\t\t\tbtnElem.id = idName;\n\n\t\t\tif (typeof def.onClick === \"function\")\n\t\t\t{\n\t\t\t\tthis[callbackName] = def.onClick;\n\t\t\t\tbtnElem.onclick = function () { Alert[callBackFuncName](opt.id); };\n\t\t\t}\n\n\t\t\treturn btnElem;\n\t\t}\n\n\t\tthis.rootElem = document.createElement(\"div\");\n\t\tthis.rootElem.className = \"bd-callout bd-callout-\" + (opt.style || \"warning\") ;\n\t\tif (opt.margin)\n\t\t{\n\t\t\tthis.rootElem.className += \" marginLeftAndRight\";\n\t\t}\n\t\tthis.rootElem.id = opt.id;\n\n\t\tvar msgElem = document.createElement(\"h4\");\n\t\tmsgElem.innerText = opt.message;\n\t\tthis.rootElem.appendChild(msgElem);\n\n\t\tif (opt.detailsBtn)\n\t\t{\n\t\t\tthis.detailsBtn = $getBtn.call(this, opt.detailsBtn, \"button-callout button-callout-warning creditScore\", \"CreditScoreButton\", \"detailCallback\", \"OnDetailAlertClick\");\n\t\t\tthis.rootElem.appendChild(this.detailsBtn);\n\t\t}\n\n\t\tcontainerElem.appendChild(this.rootElem);\n\n\t};\n\t\n\tAlert.OnDetailAlertClick = function (alertId) { alerts[alertId].detailCallback(); }\n\n\tfunction OnAddAlert(evt)\n\t{\n\t\tif (evt.id && !alerts[evt.id])\n\t\t{\n\t\t\tconst containerElem = document.getElementById(\"alertsContainer\");\n\t\t\talerts[evt.id] = new Alert(evt, containerElem);\n\t\t}\n\t}\n\n\tfunction OnAlertSetdetailsBtnVisibility(evt)\n\t{\n\t\tif (alerts[evt.id] && alerts[evt.id].detailsBtn)\n\t\t\talerts[evt.id].detailsBtn.style.display = evt.show ? \"\" : \"none\";\n\t}\n\n\tfunction OnHideAlert(evt)\n\t{\n\t\tif (alerts[evt.id])\n\t\t{\n\t\t\talerts[evt.id].rootElem.style.display = \"none\";\n\t\t\tdelete alerts[evt.id];\n\t\t}\t\n\t}\n</script>",
																				"css": ".bd-callout-FieldManager {\n\tpadding: 0;\n}\n\n\t.bd-callout-FieldManager .secondColBody {\n\t\tpadding: 0 !important;\n\t}\n\n.bd-callout {\n\tborder-left: 4px solid;\n\tborder-radius: 4px;\n}\n\n\t.bd-callout:not(:first-child) {\n\t\tmargin-top: 10px;\n\t}\n\n\t.bd-callout::after {\n\t\tcontent: \"\";\n\t\tdisplay: block;\n\t\tclear: both;\n\t}\n\n\t.bd-callout .button-callout {\n\t\tborder: 1px;\n\t\tborder-style: solid;\n\t\tbox-sizing: border-box;\n\t\tborder-radius: 4px;\n\t\tpadding: 4px;\n\t\tmargin: 6px;\n\t\tfloat: right;\n\t\tcursor: pointer;\n\t\tfont: normal 16px 'Roboto Bold';\n\t}\n\n\t.bd-callout .button-callout-danger {\n\t\tbackground-color: #E42518;\n\t\tborder-color: #E42518;\n\t\tcolor: #fce9e7;\n\t}\n\n\t.bd-callout .button-callout-warning {\n\t\tbackground-color: #ff8700;\n\t\tborder-color: #ff8700;\n\t\tcolor: #fff3e5;\n\t}\n\n\t.bd-callout .button-callout-info {\n\t\tbackground-color: #0082c0;\n\t\tborder-color: #0082c0;\n\t\tcolor: #e5f2f9;\n\t}\n\n\t.bd-callout h4 {\n\t\tfloat: left;\n\t\tline-height: 15px;\n\t\tpadding: 4px;\n\t\tmargin: 6px;\n\t\tfont: normal 16px 'Roboto Bold';\n\t\twhite-space: normal;\n\t}\n\n\t.bd-callout.bd-callout-info {\n\t\tborder-left-color: #0082c0;\n\t\tbackground-color: #e5f2f9;\n\t}\n\n\t\t.bd-callout.bd-callout-info h4 {\n\t\t\tcolor: #0082c0;\n\t\t}\n\n\t.bd-callout.bd-callout-warning {\n\t\tborder-left-color: #ff8700;\n\t\tbackground-color: #fff3e5;\n\t}\n\n\t\t.bd-callout.bd-callout-warning h4 {\n\t\t\tcolor: #ff8700;\n\t\t}\n\n\t.bd-callout.bd-callout-danger {\n\t\tborder-left-color: #E42518;\n\t\tbackground-color: #fce9e7;\n\t}\n\n\t\t.bd-callout.bd-callout-danger h4 {\n\t\t\tcolor: #E42518;\n\t\t}\n\n.marginLeftAndRight {\n\tmargin-left: -10px;\n\tmargin-right: -10px;\n}\n",
