																				"htmlContent": "<input id=\"onDisplayRiskCategory\" type=\"hidden\" onclick=\"onDisplayRiskCategory(event);\">\n<div class=\"container\">\n\t<div id=\"RiskCategoryBadgeValue\" class=\"badge\">\n\t\t<span id=\"RiskCategoryValue\"></span>\n\t</div>\n</div>\n<script>\n\twindow.postMessage({ eventName: \"onLoad\", control: \"RiskCategoryHTML__\" }, document.location.origin);\n\n\tfunction onDisplayRiskCategory(evt)\n\t{\n\t\tdocument.getElementById(\"RiskCategoryValue\").innerText = evt.value;\n\t\tif (evt.color && CSS.supports('color', evt.color))\n\t\t{\n\t\t\tdocument.getElementById(\"RiskCategoryBadgeValue\").style.backgroundColor = evt.color;\n\t\t\tdocument.getElementById(\"RiskCategoryBadgeValue\").style.color = \"white\";\n\t\t}\n\t\telse\n\t\t{\n\t\t\tdocument.getElementById(\"RiskCategoryBadgeValue\").style.backgroundColor = \"white\";\n\t\t\tdocument.getElementById(\"RiskCategoryBadgeValue\").style.color = \"#008998\"\n\t\t}\n\t}\n</script>",
																				"css": "@ .container {\n    display: inline-block;\n    flex-direction: column;\n    white-space: normal;\n    width: 100%;\n}\n\n@ .container .badge {\n\tfont-size: 16px;\n\tpadding: 0.5em;\n\tborder-radius: 4px;\n\tborder-width: 1px;\n\tdisplay: flex;\n\tjustify-content: center;\n\tmin-width: 40px;\n}\n\n@ .container .badge.veryLow {\n    background-color: #5EAD25;\n    color: white;\n}\n\n@ .container .badge.low {\n    background-color: #3FBFAD;\n    color: white;\n}\n\n@ .container .badge.moderate {\n    background-color: #F9BE00;\n    color: white;\n}\n\n@ .container .badge.medium {\n    background-color: #FF8700;\n    color: white;\n}\n\n@ .container .badge.high {\n    background-color: #D92530;\n    color: white;\n}\n\n@ .container .badge.extreme {\n    background-color: #943838;\n    color: white;\n}\n\n@ .container .badge.outofbusiness {\n    background-color: #1A2732;\n    color: white;\n}\n\n@ .container .badge.none {\n    background-color: #C0C0C0;\n    color: white;\n}\n\n@ .container .badge.default {\n    background-color: white;\n    color: #008998;\n}\n\n@ .container .badge > span {\n    font-size: 20px;\n    font-family: Roboto Bold;\n    line-height: normal;\n    display: block;\n    text-transform: uppercase;\n}\n",
