																	"*": {
																		"InvoiceMenu__": {
																			"type": "HTML",
																			"data": false,
																			"stamp": 120,
																			"options": {
																				"label": "_InvoiceMenu",
																				"htmlContent": "<input id=\"onInvoicesLoad\" type=\"hidden\" onclick=\"OnInvoicesLoad(event);\">\n<input id=\"onChangeInvoiceView\" type=\"hidden\" onclick=\"OnChangeInvoiceView(event);\">\n<div id=\"InvoicesMenu\" class=\"nav-body\" style=\"\">\n\t<ul class=\"nav-topbar\">\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"allInvoices\" onclick=\"OnClickInvoicesTab(this);\" href=\"#\" class=\"nav-link active\">\n\t\t\t\t<span id=\"allInvoicesLbl\" />\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item-divider\"></li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"overdueInvoices\" onclick=\"OnClickInvoicesTab(this);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"overdueInvoicesLbl\" />\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item-divider\"></li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"outstandingInvoices\" onclick=\"OnClickInvoicesTab(this);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"outstandingInvoicesLbl\" />\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item-divider\"></li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"60daysInvoices\" onclick=\"OnClickInvoicesTab(this);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"60daysInvoicesLbl\" />\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item-divider\"></li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"creditNotesInvoices\" onclick=\"OnClickInvoicesTab(this);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"creditNotesInvoicesLbl\" />\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item-divider\"></li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"disputeInvoices\" onclick=\"OnClickInvoicesTab(this);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"disputeInvoicesLbl\" />\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item-divider\"></li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"promiseToPay\" onclick=\"OnClickInvoicesTab(this);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"promiseToPayLbl\" />\n\t\t\t</a>\n\t\t</li>\n\t</ul>\n</div>\n<script>\n\twindow.postMessage({ eventName: \"onLoad\", control: \"InvoiceMenu__\" }, document.location.origin);\n\tvar tabEvtInvoicesItems = document.getElementById(\"InvoicesMenu\").getElementsByClassName(\"nav-link\");\n\tfunction OnClickInvoicesTab(tab)\n\t{\n\t\tfor (var i = 0; i < tabEvtInvoicesItems.length; i++)\n\t\t\ttabEvtInvoicesItems[i].className = \"nav-link\";\n\n\t\ttab.className = \"nav-link active\";\n\t\twindow.postMessage({ eventName: \"onClick\", control: \"InvoiceMenu__\", args: tab.id }, document.location.origin);\n\t}\n\n\tfunction OnChangeInvoiceView(evt)\n\t{\n\t\tfor (var i = 0; i < tabEvtInvoicesItems.length; i++)\n\t\t{\n\t\t\tif (tabEvtInvoicesItems[i].id === evt.viewName)\n\t\t\t{\n\t\t\t\tOnClickInvoicesTab(tabEvtInvoicesItems[i]);\n\t\t\t\treturn;\n\t\t\t}\n\t\t}\n\t}\n\n\tfunction OnInvoicesLoad(evt)\n\t{\n\t\tfor (var tab in evt.tabs)\n\t\t{\n\t\t\tvar spanElem = document.getElementById(tab + \"Lbl\");\n\t\t\tif (spanElem)\n\t\t\t{\n\t\t\t\tspanElem.innerText = evt.tabs[tab].trad;\n\t\t\t}\n\t\t\tvar elem = document.getElementById(tab);\n\t\t\tif (elem && evt.tabs[tab].hidden)\n\t\t\t{\n\t\t\t\telem.style.display = \"none\";\n\t\t\t\telem.parentNode.previousElementSibling.style.display = \"none\";\n\t\t\t}\n\n\t\t}\n\t}\n</script>",
																				"width": "100%",
																				"version": 0
																			}
