																	"*": {
																		"OrdersMenu__": {
																			"type": "HTML",
																			"data": false,
																			"stamp": 486,
																			"options": {
																				"label": "_OrdersMenu",
																				"htmlContent": "<input id=\"onOrdersLoad\" type=\"hidden\" onclick=\"OnOrdersLoad(event);\">\n<input id=\"onChangeOrderView\" type=\"hidden\" onclick=\"OnChangeOrderView(event);\">\n<div id=\"OrdersMenu\" class=\"nav-body\" style=\"\">\n\t<ul class=\"nav-topbar\">\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"ordersToValidate\" onclick=\"OnClickOrdersTab(this);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"ordersToValidateLbl\" />\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item-divider\"></li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"allImportedOrders\" onclick=\"OnClickOrdersTab(this);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"allImportedOrdersLbl\" />\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item-divider\"></li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"blockedOrders\" onclick=\"OnClickOrdersTab(this);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"blockedOrdersLbl\" />\n\t\t\t</a>\n\t\t</li>\n\t\t<li class=\"nav-item-divider\"></li>\n\t\t<li class=\"nav-item\">\n\t\t\t<a id=\"allRejectedOrders\" onclick=\"OnClickOrdersTab(this);\" href=\"#\" class=\"nav-link\">\n\t\t\t\t<span id=\"allRejectedOrdersLbl\" />\n\t\t\t</a>\n\t\t</li>\n\t</ul>\n</div>\n<script>\n\twindow.postMessage({ eventName: \"onLoad\", control: \"OrdersMenu__\" }, document.location.origin);\n\tvar tabEvtOrdersItems = document.getElementById(\"OrdersMenu\").getElementsByClassName(\"nav-link\");\n\tfunction OnClickOrdersTab(tab)\n\t{\n\t\tfor (var i = 0; i < tabEvtOrdersItems.length; i++)\n\t\t\ttabEvtOrdersItems[i].className = \"nav-link\";\n\n\t\ttab.className = \"nav-link active\";\n\t\twindow.postMessage({ eventName: \"onClick\", control: \"OrdersMenu__\", args: tab.id }, document.location.origin);\n\t}\n\n\tfunction OnChangeOrderView(evt)\n\t{\n\t\tfor (var i = 0; i < tabEvtOrdersItems.length; i++)\n\t\t{\n\t\t\tif (tabEvtOrdersItems[i].id === evt.viewName)\n\t\t\t{\n\t\t\t\tOnClickOrdersTab(tabEvtOrdersItems[i]);\n\t\t\t\treturn;\n\t\t\t}\n\t\t}\n\t}\n\n\tfunction OnOrdersLoad(evt)\n\t{\n\t\tvar isFirstTab = true;\n\t\tfor (var tab in evt.tabs)\n\t\t{\n\t\t\tvar spanElem = document.getElementById(tab + \"Lbl\");\n\t\t\tif (spanElem)\n\t\t\t{\n\t\t\t\tspanElem.innerText = evt.tabs[tab].trad;\n\t\t\t}\n\t\t\tvar elem = document.getElementById(tab);\n\t\t\tif(elem && isFirstTab && !evt.tabs[tab].hidden)\n\t\t\t{\n\t\t\t\tisFirstTab = false;\n\t\t\t\telem.classList.add(\"active\");\n\t\t\t}\n\t\t\tif (elem && evt.tabs[tab].hidden)\n\t\t\t{\n\t\t\t\telem.style.display = \"none\";\n\t\t\t\telem.parentNode.style.display = \"none\";\n\t\t\t\tif(elem.parentNode.nextElementSibling)\n\t\t\t\t{\n\t\t\t\t\telem.parentNode.nextElementSibling.style.display = \"none\";\n\t\t\t\t}\n\t\t\t}\n\n\t\t}\n\t}\n</script>",
																				"width": "100%",
																				"version": 0
																			}
																		},
