																	"stamp": 671,
																	"options": {
																		"version": 0,
																		"lines": 2,
																		"columns": 2,
																		"ctrlsPos": {
																			"DeductionsMenu__": {
																				"line": 1,
																				"column": 1
																			},
																			"DeductionsList__": {
																				"line": 2,
																				"column": 1
																			}
																		},
																		"colspans": [
																			[
																				{
																					"index": 0,
																					"length": 2
																				}
																			],
