																			"stamp": 813,
																			"options": {
																				"label": "HTML content",
																				"htmlContent": "<input id=\"onParentsIdLinksLoad\" type=\"hidden\" onclick=\"onParentsIdLinksLoad(event);\">\n<div>\n\t<div class=\"information parentsLinks\" style=\"display:none\"><a id=\"parentsLinks\"></a></div>\n</div>\n\n\n<script>\n    window.postMessage({ eventName: \"onParentsIdLinksLoad\", control: \"ParentsIdLinks__\" }, document.location.origin);\n\tfunction onParentsIdLinksLoad(evt) \n\t{\n\t\tvar div = document.querySelector(\".parentsLinks\");\n\t\tvar elem = document.getElementById(\"parentsLinks\");\n\t\tdiv.style.display = \"flex\";\n\n\t\tif (elem)\n\t\t{\n\t\t\tif (evt.customerInfo.parentCustomer)\n\t\t\t{\n\t\t\t\tvar parentLinkIdentifier = evt.customerInfo.parentCustomer;\n\t\t\t\telem.innerHTML = \"<a class='action-link' onclick=onClickCustomer('\" + parentLinkIdentifier.userId + \"')>\" + parentLinkIdentifier.name.toUpperCase() + \" (\" + parentLinkIdentifier.id.toUpperCase() + \")</a>\";\n\t\t\t}\n\t\t\telse\n\t\t\t{\n\t\t\t\telem.innerText = evt.translations.parentNotFound; \n\t\t\t}\n\t\t}\n\t}\n\n\tfunction onClickCustomer(userId)\n\t{\n\t\twindow.postMessage({ eventName: \"ClickCustomer\", control: \"MainContact__\", userId: userId }, document.location.origin);\n\t}\n</script>",
																				"width": "100%",
																				"version": 0
