																	"*": {
																		"MainContact__": {
																			"type": "HTML",
																			"data": false,
																			"stamp": 818,
																			"options": {
																				"label": "HTML content",
																				"htmlContent": "<input id=\"onMainContactLoad\" type=\"hidden\" onclick=\"onMainContactLoad(event);\">\n<div>\n\t<div id=\"customerDetail\">\n\t\t<div class=\"nameContact\"></div>\n\t\t<div class=\"information email\"></div>\n\t\t<div class=\"information phoneNumber\" style=\"display:none\"><i class=\"fa fa-phone fa-fw\" style=\"margin-right: 5px\" aria-hidden=\"true\"></i><a id=\"phoneNumber\"></a></div>\n\t\t<div class=\"information deliveryMethod\" style=\"display:none\"><i class=\"fa fa-truck fa-fw\" style=\"margin-right: 5px\" aria-hidden=\"true\"></i><a id=\"deliveryMethod\"></a></div>\n\t\t<div class=\"information mergedCustomers\" style=\"display:none\"><a id=\"mergedCustomers\"></a></div>\n\t</div>\n</div>\n\n\n<script>\n    window.postMessage({ eventName: \"onMainContactLoad\", control: \"MainContact__\" }, document.location.origin);\n\tfunction onMainContactLoad(evt)\n\t{\n\t\tif (evt.customerInfo.subName !== \"\")\n\t\t{\n\t\t\tdiv = document.getElementsByClassName(\"nameContact\");\n\t\t\tdiv[0].innerText = evt.customerInfo.subName;\n\t\t}\n\n\t\tif (evt.customerInfo.mergedCustomers && evt.customerInfo.mergedCustomers.length > 0)\n\t\t{\n\t\t\tvar elem = document.getElementById(\"mergedCustomers\");\n\t\t\tvar innerHTML = \"<ul>\";\n\t\t\tfor (var i = 0; i < Math.min(10, evt.customerInfo.mergedCustomers.length); i++) {\n\t\t\t\tvar customer = evt.customerInfo.mergedCustomers[i];\n\t\t\t\tvar viewmore = evt.translations.viewMore;\n\t\t\t\tinnerHTML += \"<li class='mergedCustomerLine'><a class='action-link' onclick=onClickCustomer('\" + customer.userId + \"')>\" + customer.name + \" (\" + customer.id + \")</a></li>\";\n\t\t\t}\n\t\t\tinnerHTML += \"<a class='mergedCustomerLine moreMergedCustomer action-link-display-more' onclick=onClickDisplayChildsPopup()>\" + viewmore + \"</a>\";\n\t\t\tinnerHTML += \"</ul>\";\n\t\t\telem.innerHTML = innerHTML;\n\t\t\tdiv = document.getElementsByClassName(\"mergedCustomers\");\n\t\t\tdiv[0].style.display = \"flex\";\n\t\t}\n\t\telse\n\t\t{\n\t\t\tif (evt.customerInfo.email !== \"\")\n\t\t\t{\n\t\t\t\tdiv = document.getElementsByClassName(\"email\");\n\t\t\t\tdiv[0].innerText = evt.customerInfo.email;\n\t\t\t}\n\n\t\t\tif (evt.customerInfo.phoneNumber !== \"\")\n\t\t\t{\n\t\t\t\tvar elem = document.getElementById(\"phoneNumber\");\n\t\t\t\telem.text = evt.customerInfo.phoneNumber;\n\t\t\t\tdiv = document.getElementsByClassName(\"phoneNumber\");\n\t\t\t\tdiv[0].style.display = \"block\";\n\t\t\t}\n\n\t\t\tif (evt.customerInfo.deliveryMethod !== \"\")\n\t\t\t{\n\t\t\t\tvar elem = document.getElementById(\"deliveryMethod\");\n\t\t\t\telem.text = evt.customerInfo.deliveryMethod;\n\t\t\t\tdiv = document.getElementsByClassName(\"deliveryMethod\");\n\t\t\t\tdiv[0].style.display = \"block\";\n\t\t\t}\n\t\t}\n\t}\n\n\tfunction onClickCustomer(userId)\n\t{\n\t\twindow.postMessage({ eventName: \"ClickCustomer\", control: \"MainContact__\", userId: userId }, document.location.origin);\n\t}\n\n\tfunction onClickDisplayChildsPopup()\n\t{\n\t\twindow.postMessage({ eventName: \"ClickDisplayChildsPopup\", control: \"MainContact__\" }, document.location.origin);\n\t}\n</script>",
																				"width": "100%",
																				"css": "#customerDetail {\n\tborder-radius: 5px;\n\tbackground-color: #f2f2f2;\n\tpadding-bottom: 20px;\n}\n\n.information {\n\tmargin-left: 10px;\n\tmargin-bottom: 3px;\n}\n\n.timelineContainer .timeline .subtitle {\n\twhite-space: pre-wrap;\n}\n\n.timelineContainer .timeline .title {\n\twhite-space: pre-wrap;\n}\n\n.timelineContainer .timeline .content {\n\twhite-space: pre-wrap;\n}\n\n.mergedCustomerLine {\n\tmargin-left: 30px;\n\tcursor: pointer;\n}\n\n.mergedCustomerLine:hover {\n\tcursor:pointer;\n}\n\n.action-link-display-more {\n\tcolor: #000000;\n\ttext-decoration: underline;\n\tfont-weight: bold;\n\tlist-style: none;\n}\n",
																				"version": 0
																			}
																		},
																		"ActionMenu__": {
																			"type": "HTML",
																			"data": false,
																			"stamp": 819,
																			"options": {
																				"label": "ActionMenu__",
																				"width": "100%",
																				"htmlContent": "<input id=\"onActionLoad\" type=\"hidden\" onclick=\"onActionLoad(event);\">\n<div class=\"backgroundButton\">\n\t<div class=\"nav-body\">\n\t\t<ul class=\"nav-topbar\">\n\t\t\t<li id=\"MoreDetailsElement\" class=\"nav-item action-link\">\n\t\t\t\t<a id=\"MoreDetails\" onclick=\"MoreDetails()\">_More_Details</a>\n\t\t\t</li>\n\t\t\t<li id=\"MoreDetailsDividerElement\" class=\"nav-item-divider action-divider\"></li>\n\t\t\t<li class=\"nav-item action-link\">\n\t\t\t\t<a id=\"Edit\" onclick=\"EditAction()\">_Edit</a>\n\t\t\t</li>\n\t\t\t<li class=\"nav-item-divider action-divider\"></li>\n\t\t\t<li class=\"nav-item action-link\">\n\t\t\t\t<a id=\"ResendWelcomeEmail\" onclick=\"ResendWelcomeEmailAction()\">_Resend welcome email</a>\n\t\t\t</li>\n\t\t\t<li class=\"nav-item-divider action-divider\"></li>\n\t\t\t<li class=\"nav-item action-link\">\n\t\t\t\t<a id=\"ResetPassword\" onclick=\"ResetPasswordAction()\">_Reset password</a>\n\t\t\t</li>\n\t\t</ul>\n\t</div>\n</div>\n<script>\n\twindow.postMessage({ eventName: \"onActionLoad\", control: \"ActionMenu__\" }, document.location.origin);\n\tfunction onActionLoad(evt)\n\t{\n\t\tfor (var element in evt.tabs)\n\t\t{\n\t\t\tvar elem = document.getElementById(element);\n\t\t\tif (elem)\n\t\t\t\telem.innerText = evt.tabs[element];\n\t\t}\n\n\t\t/*if (!evt.isMainContact)\n\t\t{\n\t\t\tdocument.getElementById(\"MoreDetailsElement\").style.display = \"none\";\n\t\t\tdocument.getElementById(\"MoreDetailsDividerElement\").style.display = \"none\";\n\t\t}*/\n\t}\n\n\tfunction EditAction()\n\t{\n\t\twindow.postMessage({ eventName: \"EditAction\", control: \"ActionMenu__\" }, document.location.origin);\n\t}\n\n\tfunction ResendWelcomeEmailAction()\n\t{\n\t\twindow.postMessage({ eventName: \"WelcomeEmailAction\", control: \"ActionMenu__\" }, document.location.origin);\n\t}\n\n\tfunction ResetPasswordAction()\n\t{\n\t\twindow.postMessage({ eventName: \"ResetPasswordAction\", control: \"ActionMenu__\" }, document.location.origin);\n\t}\n\n\tfunction MoreDetails()\n\t{\n\t\twindow.postMessage({ eventName: \"MoreDetails\", control: \"ActionMenu__\" }, document.location.origin);\n\t}\n</script>",
																				"css": ".action-link {\n\tcolor: #008998;\n\ttext-decoration: underline;\n\tcursor: pointer;\n}\n\n.action-divider {\n\tbackground-color: #008998 !important;\n\tmargin-right: 10px !important;\n\tmargin-left: 10px !important;\n}\n\n.backgroundButton {\n\tborder-radius: 10px;\n\tbackground-color: #f2f2f2;\n\tmargin-top: -22px;\n\tmargin-bottom: 2px;\n\tpadding-left: 10px;\n\tpadding-bottom: 5px;\n}\n",
