															"*": {
																"Grid": {
																	"type": "GridLayout",
																	"data": [
																		"fields"
																	],
																	"stamp": 842,
																	"options": {
																		"version": 0,
																		"lines": 1,
																		"columns": 2,
																		"ctrlsPos": {
																			"LastInternalNote__": {
																				"line": 1,
																				"column": 1
