																	"*": {
																		"LastInternalNote__": {
																			"type": "HTML",
																			"data": false,
																			"stamp": 843,
																			"options": {
																				"label": "HTML content",
																				"htmlContent": "<input id=\"onLastInternalNoteLoading\" type=\"hidden\" onclick=\"onLastInternalNoteLoading(event);\">\n<input id=\"onLastInternalNoteLoad\" type=\"hidden\" onclick=\"onLastInternalNoteLoad(event);\">\n<div>\n\n\t<div id=\"loader\"></div>\n\n\t<div id=\"lastInternalNote\">\n\t\t<div id=\"lastInternalNoteContent\" class=\"information content\"></div>\n\t\t<div class=\"information\">\n\t\t\t<span id=\"lastInternalNoteDate\" class=\"date\"></span>\n\t\t</div>\n\t</div>\n\n\t<div class=\"nav-body\">\n\t\t<ul class=\"nav-topbar\">\n\t\t\t<li id=\"ViewAllNotesElement\" class=\"nav-item action-link\">\n\t\t\t\t<a id=\"ViewAllNotes\" onclick=\"GoToInternalNotesTab()\">_View_all_notes</a>\n\t\t\t</li>\n\t\t\t<li id=\"MoreDetailsDividerElement\" class=\"nav-item-divider action-divider\"></li>\n\t\t\t<li class=\"nav-item action-link\">\n\t\t\t\t<a id=\"NewInternalNote\" onclick=\"NewInternalNoteAction()\">_New_Internal_Note</a>\n\t\t\t</li>\n\t\t</ul>\n\t</div>\n\n</div>\n\n<script>\n\twindow.postMessage({ eventName: \"onLoad\", control: \"LastInternalNote__\" }, document.location.origin);\n\n\tfunction onLastInternalNoteLoading(evt)\n\t{\n\t\t\n\t\tfor (var id in evt.translations)\n\t\t{\n\t\t\tvar elem = document.getElementById(id);\n\t\t\tif (elem)\n\t\t\t\telem.innerText = evt.translations[id];\n\t\t}\n\t\tvar loader = document.getElementById(\"loader\");\n\t\tif (loader)\n\t\t\tloader.innerHTML = evt.imgElemHtml;\n\t}\n\n\tfunction GoToInternalNotesTab()\n\t{\n\t\twindow.postMessage({ eventName: \"openInternalNotesTab\", control: \"LastInternalNote__\" }, document.location.origin);\n\t}\n\n\tfunction onLastInternalNoteLoad(evt)\n\t{\n\n\t\tif (evt.lastInternalNote)\n\t\t{\n\t\t\tvar elemContent = document.getElementById(\"lastInternalNoteContent\");\n\t\t\tif (elemContent)\n\t\t\t\telemContent.innerText = evt.lastInternalNote.content;\n\n\t\t\tvar elemDate = document.getElementById(\"lastInternalNoteDate\");\n\t\t\tif (elemDate)\n\t\t\t\telemDate.innerText = evt.lastInternalNote.date;\n\t\t}\n\t\telse \n\t\t{\n\t\t\tvar elemContent = document.getElementById(\"lastInternalNoteContent\");\n\t\t\tif (elemContent)\n\t\t\t\telemContent.innerText = evt.translations.NoLastInternalNote;\n\t\t}\n\n\t\tvar loader = document.getElementById(\"loader\");\n\t\tif (loader)\n\t\t\tloader.style.display = \"none\";\n\n\t}\n\n\tfunction NewInternalNoteAction()\n\t{\n\t\twindow.postMessage({ eventName: \"NewInternalNoteAction\", control: \"LastInternalNote__\" }, document.location.origin);\n\t}\n\n</script>\n",
																				"width": "100%",
																				"css": "#lastInternalNote {\n\tborder-radius: 5px;\n\tbackground-color: #f2f2f2;\n\twhite-space: initial;\n}\n\n#lastInternalNoteDate {\n\tfont-size: 10px;\n}\n",
																				"version": 0
																			}
																		}
																	}
																}
															}
														}
													}
												}
											}
										}
									}
